## first question

text = ""
pattern = "CTGTCAGCT"

def patternCount(text, pattern):
    count = 0
    for i in range(len(text) - len(pattern)):
        print(text[i:i + len(pattern)])
        if(text[i:i+len(pattern)] == pattern):
            count = count + 1
    return count

print(patternCount(text, pattern))

## second question

text = ""

def frequency(text, k):
    dictionary = {}
    max = 0;
    finalString = "";
    for i in range(len(text) - k):
        key = text[i:i+k]
        if key in dictionary:
            dictionary[key] = dictionary[key] + 1
        else:
            dictionary[key] = 1
    
        if dictionary[key] > max:
            max = dictionary[key]

    for key, value in dictionary.items():
        if(value == max):
            finalString = finalString + key + " "

    print(max)
    return (finalString.strip(), max)
        

print(frequency(text, 11))

## Question 3 reverse complement

text = ""
dictionary = {
    "A":"T",
    "C":"G",
    "T":"A",
    "G":"C"
}

def reverseComplement(text):
    complementString = "";
    for i in range(len(text)):
        complementString = complementString + dictionary[text[i]]
    return complementString[::-1]

print(reverseComplement(text))

## Question 4 search for entire pattern in the genome

genome = ""
pattern = "CTCTAATCT"

def findPattern(genome, pattern):
    string = ""
    for i in range(len(genome) - len(pattern)):
        if genome[i:i+len(pattern)] == pattern:
            string += str(i) + " "

    print(string)

findPattern(genome, pattern)

